import React from "react";

/*
  VIGHNAVI ACADEMY
  About Us Page
  Header and Footer intentionally excluded.

  Required:
    React 18+

  Optional:
    You can replace the image URLs with your own academy images.
*/

const styles = `
  * {
    box-sizing: border-box;
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    margin: 0;
    font-family:
      Inter,
      -apple-system,
      BlinkMacSystemFont,
      "Segoe UI",
      Roboto,
      Helvetica,
      Arial,
      sans-serif;
    color: #17343b;
    background: #ffffff;
  }

  button,
  a {
    font-family: inherit;
  }

  button {
    cursor: pointer;
  }

  .academy-page {
    width: 100%;
    overflow: hidden;
    background: #ffffff;
  }

  /* =========================================================
     COMMON
  ========================================================= */

  .container {
    width: min(1180px, calc(100% - 48px));
    margin: 0 auto;
  }

  .section-label {
    margin: 0 0 8px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 2.4px;
    text-transform: uppercase;
    color: #075b5d;
  }

  .section-title {
    margin: 0;
    color: #103b43;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(30px, 3vw, 44px);
    line-height: 1.08;
    font-weight: 700;
  }

  .section-description {
    margin: 8px 0 0;
    color: #5c6b70;
    font-size: 15px;
    line-height: 1.55;
  }

  .gold-text {
    color: #b88a22;
  }

  .teal-text {
    color: #075b5d;
  }

  /* =========================================================
     HERO
  ========================================================= */

  .hero-section {
    position: relative;
    min-height: 520px;
    background:
      radial-gradient(
        circle at 12% 25%,
        rgba(215, 237, 235, 0.85),
        transparent 32%
      ),
      linear-gradient(
        115deg,
        #f4fbfa 0%,
        #ffffff 49%,
        #edf8f6 100%
      );
  }

  .hero-container {
    min-height: 520px;
    display: grid;
    grid-template-columns: 43% 57%;
    align-items: center;
  }

  .hero-content {
    position: relative;
    z-index: 3;
    padding: 55px 10px 50px 0;
  }

  .hero-label {
    color: #075b5d;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 2.6px;
    margin-bottom: 8px;
  }

  .hero-title {
    margin: 0;
    color: #123b43;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(42px, 4.2vw, 63px);
    line-height: 0.98;
    letter-spacing: -1.7px;
    font-weight: 700;
  }

  .hero-title .gold {
    display: block;
    color: #b78a24;
  }

  .hero-description {
    max-width: 520px;
    margin: 18px 0 20px;
    color: #4f6065;
    font-size: 15px;
    line-height: 1.55;
  }

  .hero-actions {
    display: flex;
    gap: 18px;
    flex-wrap: wrap;
  }

  .primary-button {
    border: none;
    background: #075e60;
    color: #ffffff;
    min-height: 46px;
    padding: 0 22px;
    border-radius: 25px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    font-size: 13px;
    font-weight: 700;
    transition: all 0.25s ease;
    box-shadow: 0 7px 20px rgba(7, 94, 96, 0.18);
  }

  .primary-button:hover {
    background: #064d4f;
    transform: translateY(-2px);
  }

  .secondary-button {
    border: 1.5px solid #c89d39;
    background: #ffffff;
    color: #173e44;
    min-height: 46px;
    padding: 0 23px;
    border-radius: 25px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    font-size: 13px;
    font-weight: 700;
    transition: all 0.25s ease;
  }

  .secondary-button:hover {
    background: #fffaf0;
    transform: translateY(-2px);
  }

  .arrow {
    font-size: 20px;
    line-height: 1;
  }

  .hero-mini-features {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    max-width: 500px;
    margin-top: 24px;
  }

  .hero-mini-feature {
    min-height: 56px;
    padding-right: 17px;
    margin-right: 16px;
    border-right: 1px solid #d1dddd;
  }

  .hero-mini-feature:last-child {
    border-right: none;
  }

  .mini-icon {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #075e60;
    font-size: 23px;
    margin-bottom: 2px;
  }

  .mini-feature-title {
    color: #243f44;
    font-size: 12px;
    line-height: 1.25;
  }

  .hero-image-area {
    position: relative;
    height: 100%;
    min-height: 520px;
  }

  .hero-image {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
  }

  .hero-image-overlay {
    position: absolute;
    inset: 0;
    background:
      linear-gradient(
        90deg,
        #f4fbfa 0%,
        rgba(244, 251, 250, 0.83) 6%,
        rgba(244, 251, 250, 0.15) 30%,
        rgba(0, 0, 0, 0) 65%
      );
  }

  .hero-message {
    position: absolute;
    z-index: 2;
    right: 12px;
    top: 28px;
    width: 135px;
    color: #152e34;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 22px;
    line-height: 1.08;
    font-style: italic;
    transform: rotate(-4deg);
  }

  .hero-message::after {
    content: "";
    position: absolute;
    right: 0;
    bottom: -13px;
    width: 72px;
    height: 3px;
    border-radius: 10px;
    background: #b68a25;
    transform: rotate(-7deg);
  }

  .hero-books {
    position: absolute;
    right: 12px;
    bottom: 22px;
    z-index: 3;
    width: 142px;
  }

  .hero-book {
    height: 27px;
    margin-top: 2px;
    padding-left: 15px;
    display: flex;
    align-items: center;
    border-radius: 2px 5px 5px 2px;
    background:
      linear-gradient(
        180deg,
        #174b4c,
        #0a3539
      );
    color: #e7c767;
    font-family: Georgia, serif;
    font-size: 13px;
    font-weight: 700;
    box-shadow: 0 3px 5px rgba(0, 0, 0, 0.24);
  }

  /* =========================================================
     STATS
  ========================================================= */

  .stats-section {
    background: #edf8f6;
    border-top: 1px solid #e0efed;
    border-bottom: 1px solid #e0efed;
  }

  .stats-grid {
    min-height: 95px;
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    align-items: center;
  }

  .stat-item {
    position: relative;
    text-align: center;
    padding: 13px 15px;
  }

  .stat-item:not(:last-child)::after {
    content: "";
    position: absolute;
    width: 1px;
    height: 42px;
    right: 0;
    top: 50%;
    transform: translateY(-50%);
    background: #c8deda;
  }

  .stat-icon {
    color: #075e60;
    font-size: 26px;
    height: 30px;
  }

  .stat-number {
    margin-top: 1px;
    color: #075e60;
    font-size: 17px;
    font-weight: 800;
  }

  .stat-label {
    color: #435b60;
    margin-top: 1px;
    font-size: 12px;
  }

  /* =========================================================
     STORY
  ========================================================= */

  .story-section {
    padding: 52px 0 45px;
    background: #ffffff;
  }

  .story-grid {
    display: grid;
    grid-template-columns: 47% 53%;
    gap: 28px;
    align-items: center;
  }

  .story-image-wrap {
    position: relative;
    min-height: 360px;
    overflow: hidden;
    border-radius: 13px;
    background: #dfecea;
  }

  .story-image {
    width: 100%;
    height: 100%;
    min-height: 360px;
    display: block;
    object-fit: cover;
  }

  .story-image-wrap::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
      180deg,
      rgba(0, 0, 0, 0) 50%,
      rgba(0, 40, 42, 0.3) 100%
    );
  }

  .story-quote {
    position: absolute;
    z-index: 2;
    left: 25px;
    bottom: 20px;
    width: 245px;
    padding: 18px 22px;
    border-radius: 13px;
    background: rgba(4, 77, 76, 0.91);
    color: #ffffff;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 20px;
    line-height: 1.17;
    box-shadow: 0 12px 25px rgba(0, 0, 0, 0.15);
  }

  .quote-mark {
    display: block;
    margin-bottom: 4px;
    font-size: 27px;
    font-weight: 700;
  }

  .story-content {
    padding: 5px 0 0;
  }

  .story-title {
    margin: 0 0 7px;
    color: #123b43;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(28px, 3vw, 38px);
    line-height: 1.08;
  }

  .story-text {
    margin: 0 0 10px;
    color: #59696e;
    font-size: 14px;
    line-height: 1.5;
  }

  .story-cards {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
    margin-top: 12px;
  }

  .story-card {
    min-height: 105px;
    padding: 12px 11px;
    border: 1px solid #dbe7e6;
    border-radius: 13px;
    background: #ffffff;
    box-shadow: 0 5px 15px rgba(20, 55, 60, 0.025);
  }

  .story-card-icon {
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    color: #075e60;
    font-size: 23px;
  }

  .story-card-title {
    margin-top: 4px;
    color: #143d43;
    font-size: 12px;
    font-weight: 800;
  }

  .story-card-text {
    margin-top: 4px;
    color: #65757a;
    font-size: 10px;
    line-height: 1.35;
  }

  /* =========================================================
     COURSES
  ========================================================= */

  .courses-section {
    padding: 40px 0 30px;
    background:
      linear-gradient(
        120deg,
        #edf9f7 0%,
        #f5fbfa 50%,
        #eef9f7 100%
      );
  }

  .courses-header {
    display: flex;
    align-items: end;
    justify-content: space-between;
    gap: 25px;
    margin-bottom: 18px;
  }

  .courses-header-text {
    flex: 1;
  }

  .view-all-button {
    flex-shrink: 0;
    min-height: 43px;
    border: none;
    padding: 0 20px;
    border-radius: 23px;
    background: #edbf57;
    color: #173b41;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    font-size: 12px;
    font-weight: 800;
    box-shadow: 0 7px 15px rgba(182, 138, 36, 0.12);
    transition: 0.25s ease;
  }

  .view-all-button:hover {
    background: #dfae42;
    transform: translateY(-2px);
  }

  .courses-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
  }

  .course-card {
    position: relative;
    min-height: 258px;
    padding: 13px 13px 12px;
    border: 1px solid #e2e9e8;
    border-radius: 11px;
    background: rgba(255, 255, 255, 0.97);
    box-shadow: 0 4px 15px rgba(14, 65, 68, 0.035);
    display: flex;
    flex-direction: column;
    transition:
      transform 0.25s ease,
      box-shadow 0.25s ease;
  }

  .course-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 13px 28px rgba(14, 65, 68, 0.1);
  }

  .course-top {
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 43px;
  }

  .course-icon {
    width: 48px;
    height: 42px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    background: #f4f8f8;
    color: #075e60;
    font-size: 28px;
  }

  .course-title {
    margin: 0;
    color: #153d44;
    font-size: 15px;
    line-height: 1.12;
    font-weight: 800;
  }

  .course-description {
    min-height: 45px;
    margin: 7px 0 3px;
    color: #607075;
    font-size: 11px;
    line-height: 1.32;
  }

  .topics-title {
    margin-top: 2px;
    color: #075b5d;
    font-size: 11px;
    font-weight: 800;
  }

  .topics-list {
    margin: 3px 0 9px;
    padding: 0;
    list-style: none;
  }

  .topics-list li {
    position: relative;
    margin: 2px 0;
    padding-left: 14px;
    color: #59696e;
    font-size: 10.5px;
    line-height: 1.22;
  }

  .topics-list li::before {
    content: "✓";
    position: absolute;
    left: 0;
    top: 0;
    color: #d39f27;
    font-weight: 900;
  }

  .course-button {
    width: 100%;
    min-height: 27px;
    margin-top: auto;
    border: 1px solid #e7c978;
    border-radius: 7px;
    background: #ffffff;
    color: #1c464b;
    font-size: 10px;
    font-weight: 700;
    transition: 0.2s ease;
  }

  .course-button:hover {
    background: #fff8e8;
    border-color: #c99d38;
  }

  /* =========================================================
     PROMO CARD
  ========================================================= */

  .promo-card {
    position: relative;
    min-height: 258px;
    overflow: hidden;
    border-radius: 11px;
    background: #075a5a;
  }

  .promo-image {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .promo-overlay {
    position: absolute;
    inset: 0;
    background:
      linear-gradient(
        90deg,
        rgba(2, 67, 67, 0.94) 0%,
        rgba(2, 67, 67, 0.72) 42%,
        rgba(2, 67, 67, 0.12) 100%
      );
  }

  .promo-content {
    position: relative;
    z-index: 2;
    width: 58%;
    padding: 19px 13px;
    color: #ffffff;
  }

  .promo-title {
    margin: 0;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 21px;
    line-height: 1.08;
    font-style: italic;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .promo-subtitle {
    margin-top: 27px;
    color: #ffffff;
    font-size: 13px;
    line-height: 1.2;
    font-weight: 700;
  }

  .promo-line {
    position: absolute;
    left: 12px;
    bottom: 18px;
    width: 92px;
    height: 3px;
    border-radius: 10px;
    background: #e8c159;
    transform: rotate(-8deg);
  }

  .promo-heart {
    margin-left: 8px;
    color: #edc95b;
    font-size: 20px;
  }

  /* =========================================================
     BENEFITS
  ========================================================= */

  .benefits-section {
    padding: 13px 0 20px;
    background: #ffffff;
  }

  .benefits-inner {
    min-height: 67px;
    padding: 7px 14px;
    border-radius: 35px;
    background: #fbf6e9;
    display: flex;
    align-items: center;
    gap: 7px;
  }

  .benefits-list {
    flex: 1;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    align-items: center;
  }

  .benefit {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 0 8px;
  }

  .benefit-icon {
    width: 38px;
    height: 38px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #efc967;
    color: #173d42;
    font-size: 18px;
    box-shadow: inset 0 0 0 1px rgba(137, 99, 18, 0.12);
  }

  .benefit-text {
    color: #273e42;
    font-size: 11px;
    line-height: 1.18;
    font-weight: 600;
  }

  .journey-button {
    flex-shrink: 0;
    min-height: 45px;
    padding: 0 21px;
    border: none;
    border-radius: 25px;
    background: #e8b94d;
    color: #173b40;
    font-size: 12px;
    font-weight: 800;
    display: flex;
    align-items: center;
    gap: 13px;
    transition: 0.25s ease;
  }

  .journey-button:hover {
    background: #dba936;
    transform: translateY(-2px);
  }

  /* =========================================================
     TABLET
  ========================================================= */

  @media (max-width: 1000px) {

    .hero-container {
      grid-template-columns: 48% 52%;
    }

    .hero-title {
      font-size: 44px;
    }

    .hero-description {
      font-size: 13px;
    }

    .hero-mini-feature {
      padding-right: 9px;
      margin-right: 9px;
    }

    .hero-image-area {
      min-height: 470px;
    }

    .hero-section,
    .hero-container {
      min-height: 470px;
    }

    .courses-grid {
      grid-template-columns: repeat(2, 1fr);
    }

    .promo-card {
      min-height: 258px;
    }

    .story-grid {
      grid-template-columns: 45% 55%;
    }

    .story-cards {
      gap: 6px;
    }

    .story-card {
      padding: 10px;
    }

    .benefits-inner {
      border-radius: 20px;
      flex-direction: column;
      padding: 10px;
    }

    .benefits-list {
      width: 100%;
    }

    .journey-button {
      width: 100%;
      justify-content: center;
    }
  }

  /* =========================================================
     MOBILE
  ========================================================= */

  @media (max-width: 700px) {

    .container {
      width: min(100% - 30px, 560px);
    }

    .hero-section {
      min-height: auto;
    }

    .hero-container {
      min-height: auto;
      display: flex;
      flex-direction: column;
    }

    .hero-content {
      width: 100%;
      padding: 38px 0 25px;
    }

    .hero-title {
      font-size: clamp(39px, 11vw, 54px);
      letter-spacing: -1px;
    }

    .hero-description {
      font-size: 14px;
    }

    .hero-image-area {
      width: 100%;
      height: 360px;
      min-height: 360px;
    }

    .hero-message {
      right: 8px;
      font-size: 19px;
    }

    .hero-books {
      right: 10px;
      bottom: 15px;
      width: 112px;
    }

    .hero-book {
      height: 23px;
      font-size: 11px;
    }

    .hero-mini-features {
      max-width: none;
      width: 100%;
    }

    .hero-mini-feature {
      padding-right: 8px;
      margin-right: 8px;
    }

    .stats-grid {
      grid-template-columns: repeat(2, 1fr);
      padding: 8px 0;
    }

    .stat-item {
      padding: 10px 5px;
    }

    .stat-item:nth-child(2)::after,
    .stat-item:nth-child(4)::after {
      display: none;
    }

    .stat-item:last-child {
      grid-column: 1 / -1;
    }

    .story-section {
      padding: 38px 0;
    }

    .story-grid {
      grid-template-columns: 1fr;
      gap: 25px;
    }

    .story-image-wrap {
      min-height: 300px;
    }

    .story-image {
      min-height: 300px;
    }

    .story-cards {
      grid-template-columns: 1fr;
      gap: 9px;
    }

    .story-card {
      min-height: auto;
    }

    .courses-section {
      padding: 35px 0 25px;
    }

    .courses-header {
      align-items: flex-start;
      flex-direction: column;
    }

    .view-all-button {
      width: 100%;
      justify-content: center;
    }

    .courses-grid {
      grid-template-columns: 1fr;
    }

    .course-card,
    .promo-card {
      min-height: 245px;
    }

    .benefits-list {
      grid-template-columns: repeat(2, 1fr);
      gap: 10px;
    }

    .benefit {
      padding: 4px;
    }

    .journey-button {
      min-height: 46px;
    }
  }

  /* =========================================================
     SMALL MOBILE
  ========================================================= */

  @media (max-width: 430px) {

    .hero-actions {
      flex-direction: column;
    }

    .primary-button,
    .secondary-button {
      width: 100%;
    }

    .hero-mini-features {
      grid-template-columns: 1fr;
      gap: 12px;
    }

    .hero-mini-feature {
      border-right: none;
      border-bottom: 1px solid #d1dddd;
      padding-bottom: 9px;
      margin-right: 0;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .hero-mini-feature:last-child {
      border-bottom: none;
    }

    .mini-icon {
      margin: 0;
    }

    .stats-grid {
      grid-template-columns: 1fr 1fr;
    }

    .story-quote {
      width: calc(100% - 30px);
      left: 15px;
      font-size: 18px;
    }

    .benefits-list {
      grid-template-columns: 1fr;
    }

    .benefit {
      width: 100%;
    }
  }
`;


